    "difficulty": "medium",
    "questionEn": "What were the principal stipulations of the 1930 Anglo-Iraqi Treaty that governed Iraq's admission to the League of Nations in 1932?",
    "questionAr": "ما الشروط الأساسية التي تضمنتها معاهدة 1930م بين بريطانيا والعراق والتي مهدت لدخول العراق عصبة الأمم عام 1932م؟",
    "optionsEn": [
      "Granting Iraq nominal political independence and League of Nations membership, while allowing Britain to maintain strategic military airbases at Habbaniyah and Shaibah, and retain British military transit rights",
      "Ceding all northern oil fields in Kirkuk entirely to the French petroleum cartel",
      "Annexing the Kingdom of Iraq directly into British India",
      "Disbanding the Iraqi army and replacing it with United Nations peacekeepers"
    ],
    "optionsAr": [
      "منح العراق استقلالاً اسمياً ودخول عصبة الأمم، مع احتفاظ بريطانيا بقاعدتين جويتين استراتيجيتين في الحبانية والشعيبة، وحق مرور القوات البريطانية",
      "التنازل عن جميع حقول بترول كركوك بالكامل لصالح الشركات الفرنسية",
      "ضم المملكة العراقية رسمياً وبشكل مباشر لحكومة الهند البريطانية",
      "حل الجيش العراقي واستبداله بقوات حفظ سلام تابعة لعصبة الأمم"
    ],
    "correctAnswer": "Granting Iraq nominal political independence and League of Nations membership, while allowing Britain to maintain strategic military airbases at Habbaniyah and Shaibah, and retain British military transit rights",
    "correctIndex": 0,
    "hintEn": "Britain granted sovereignty on paper while keeping airbases at Habbaniyah and Shaibah.",
    "hintAr": "استقلال منقوص مع بقاء القواعد الجوية البريطانية وحق التدخل في حالة الحرب.",
    "stepByStepSolutionEn": [
      "1. Signed in 1930 by Prime Minister Nuri al-Said, the treaty established an alliance.",
      "2. Iraq became the first Arab state to join the League of Nations (1932), though British airbases restricted full national sovereignty."
    ],
    "stepByStepSolutionAr": [
      "١. وقعت حكومة نوري السعيد معاهدة 1930م مع بريطانيا، ونصت على إنهاء الانتداب شكلياً.",
      "٢. دخل العراق عصبة الأمم عام 1932م كدولة مستقلة، لكن مع بقاء القواعد العسكرية البريطانية في الحبانية والشعيبة وتكبيل السيادة الوطنية."
    ],
    "teacherTipEn": "Recognize that Britain replaced direct military rule with indirect control (monarchy and treaties) to curb revolutionary nationalism while retaining airbases.",
    "teacherTipAr": "انتبه إلى تحول بريطانيا من الحكم العسكري المباشر إلى السيطرة غير المباشرة (الملكية والمعاهدات والقواعد الجوية) لامتصاص الثورات الشعبية."
