    "difficulty": "medium",
    "questionEn": "Why was the Battle of Turaba fought in May 1919 between the forces of Abdulaziz Al Saud and the Hashemites a critical turning point in modern Arabian history?",
    "questionAr": "لماذا تُعد معركة «تربة» التي دارت في مايو 1919م بين قوات عبد العزيز آل سعود والجيش الهاشمي نقطة تحول حاسمة في تاريخ الجزيرة العربية؟",
    "optionsEn": [
      "Because the Ikhwan warriors of Ibn Saud decisively annihilated the Hashemite army led by Prince Abdullah bin Hussein, permanently breaking the military power of the Kingdom of Hijaz and opening the pathway to the Saudi conquest of Mecca and Jeddah",
      "Because Sharif Hussein successfully conquered Riyadh and declared himself King of Arabia",
      "Because Great Britain deployed tanks to defend the borders of Taif against all Arab tribes",
      "Because the Ottoman fleet retook Medina and exiled the Saudi leadership"
    ],
    "optionsAr": [
      "لأن قوات الإخوان التابعة لابن سعود سحقت الجيش الهاشمي بقيادة الأمير عبد الله بن الحسين، مما كسر شوكة الحجاز العسكرية وفتح الطريق لاحقاً لضم مكة وجدة",
      "لنجاح الشريف حسين في السيطرة على الرياض وإعلان نفسه ملكاً على كامل بلاد العرب",
      "لتدخل الدبابات البريطانية للدفاع عن حدود الطائف ضد جميع القبائل العربية",
      "لنجاح الأسطول العثماني في استعادة المدينة المنورة ونفي القيادة السعودية"
    ],
    "correctAnswer": "Because the Ikhwan warriors of Ibn Saud decisively annihilated the Hashemite army led by Prince Abdullah bin Hussein, permanently breaking the military power of the Kingdom of Hijaz and opening the pathway to the Saudi conquest of Mecca and Jeddah",
    "correctIndex": 0,
    "hintEn": "Turaba shattered Hashemite military supremacy in the Hijaz.",
    "hintAr": "هزيمة الجيش الهاشمي في تربة مهدت لإنهاء حكم الشريف حسين في الحجاز لاحقاً.",
    "stepByStepSolutionEn": [
      "1. In May 1919, Prince Abdullah invaded the border oasis of Turaba.",
      "2. Ibn Saud's Ikhwan launched a surprise night attack, destroying Abdullah's army.",
      "3. This battle demonstrated that the Hashemites could not defend Hijaz without British military intervention, which London refused to provide."
    ],
    "stepByStepSolutionAr": [
      "١. في مايو 1919م، تقدم الأمير عبد الله بقواته الهاشمية واحتل واحة تربة الحدودية.",
      "٢. شنت قوات الإخوان التابعة لابن سعود هجوماً ليلياً كاسحاً أباد معظم الجيش الهاشمي ونجا الأمير عبد الله بأعجوبة.",
      "٣. برهنت المعركة على عجز الشريف حسين عن حماية مملكته بمفرده دون مساندة بريطانية، فمهدت لسقوط الحجاز عام 1924–1925م."
    ],
    "teacherTipEn": "Notice King Abdulaziz's methodical phased diplomacy, eliminating rivals sequentially while exercising statecraft in the 1934 Treaty of Taif.",
    "teacherTipAr": "لاحظ التدرج السياسي للملك عبد العزيز بالقضاء على خصومه مرحلياً وترفعه الدبلوماسي الحكيم في معاهدة الطائف 1934م لترسيخ حسن الجوار."
